package com.example.complaintmanagement.security; import com.example.complaintmanagement.entity.User; import com.example.complaintmanagement.repository.UserRepository; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class CustomUserDetailsService implements UserDetailsService { private final UserRepository repo; public CustomUserDetailsService(UserRepository r){repo=r;} public UserDetails loadUserByUsername(String u){User x=repo.findByUsername(u).orElseThrow(()->new UsernameNotFoundException("User not found")); return new org.springframework.security.core.userdetails.User(x.getUsername(),x.getPassword(),x.isActive(),true,true,true,List.of(new SimpleGrantedAuthority("ROLE_"+x.getRole().name()))); } }